class Solution:
    def isPalindrome(self, s: str) -> bool:
        l, r = 0, len(s) - 1
        while l < r:
            while l < r and not s[l].isalnum():
                l += 1  # viz:skip_l
            while l < r and not s[r].isalnum():
                r -= 1  # viz:skip_r
            if s[l].lower() != s[r].lower():  # viz:compare
                return False
            l += 1
            r -= 1
        return True  # viz:done
